int register_service(struct service_registry* registry, char* service_name, char* service_addr) {
    // 检查参数是否为空
    if (registry == NULL || service_name == NULL || service_addr == NULL) {
        return -1;
    }

    // 检查服务注册表是否已满
    if (registry->count >= 64) {
        return -1;
    }

    // 检查服务名称和地址是否为空字符串
    if (strlen(service_name) == 0 || strlen(service_addr) == 0) {
        return -1;
    }

    // 检查服务名称和地址长度是否超出限制
    if (strlen(service_name) >= 128 || strlen(service_addr) >= 256) {
        return -1;
    }

    // 检查服务名称是否已存在，避免重复注册
    for (int i = 0; i < registry->count; i++) {
        if (strcmp(registry->services[i], service_name) == 0) {
            // 如果服务已存在，更新其地址
            strncpy(registry->addresses[i], service_addr, 255);
            registry->addresses[i][255] = '\0';
            return 0;
        }
    }

    // 将服务名称和地址复制到注册表中
    strncpy(registry->services[registry->count], service_name, 127);
    registry->services[registry->count][127] = '\0';

    strncpy(registry->addresses[registry->count], service_addr, 255);
    registry->addresses[registry->count][255] = '\0';

    // 增加计数器
    registry->count++;

    return 0;
}
